INSERT INTO _migration_610_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igphy_thermal_s3_001', 'topic_igcse_physics_thermal', 'subj_igcse_physics', 'igcse', NULL, NULL, 'Thermal energy is conducted through one end of a metal rod to the other. Which statement correctly describes conduction in a solid?', 'multiple_choice', NULL, '["A. Particles flow from the hot end of the rod to the cold end","B. Energy travels through the rod as infrared waves","C. Energy is transferred as vibrating particles pass energy to neighbouring particles, without the particles moving through the solid","D. Hot, less-dense regions of the metal rise towards the cold end"]', 'C', 'In conduction the particles at the hot end vibrate more vigorously and pass energy to their neighbours through collisions (in metals, free electrons also carry energy); the particles themselves stay in their fixed positions. A flow of particles or of hot, less-dense material describes convection in a fluid, and infrared waves describe radiation, which needs no medium. Therefore the correct answer is C: Energy is transferred as vibrating particles pass energy to neighbouring particles, without the particles moving through the solid.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igphy_thermal_s3_002', 'topic_igcse_physics_thermal', 'subj_igcse_physics', 'igcse', NULL, NULL, 'A 0.50 kg aluminium block of specific heat capacity 900 J/(kg °C) is heated from 20 °C to 70 °C. Calculate the thermal energy transferred to the block.', 'multiple_choice', NULL, '["A. 45,000 J","B. 9,000 J","C. 31,500 J","D. 22,500 J"]', 'D', 'The temperature rise is ΔT = 70 − 20 = 50 °C, so E = mcΔT = 0.50 × 900 × 50 = 22,500 J. (31,500 J uses the final temperature 70 °C instead of the temperature change; 9,000 J uses the initial temperature 20 °C; 45,000 J doubles the mass.) Therefore the correct answer is D: 22,500 J.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igphy_thermal_s3_003', 'topic_igcse_physics_thermal', 'subj_igcse_physics', 'igcse', NULL, NULL, 'Why does evaporation cause the temperature of the remaining liquid to fall?', 'multiple_choice', NULL, '["A. The fastest-moving (most energetic) molecules escape from the surface, so the average kinetic energy of the molecules left behind decreases","B. Evaporation draws cold air from the surroundings into the liquid","C. The slowest molecules leave the liquid first, taking no energy with them","D. Energy is destroyed as the liquid turns into a gas"]', 'A', 'Temperature is a measure of the average kinetic energy of the molecules. The molecules with the greatest kinetic energy are the ones that escape from the surface during evaporation, so the average kinetic energy — and hence the temperature — of the remaining liquid falls. The energy is carried away by the vapour (latent heat), not destroyed. Therefore the correct answer is A: The fastest-moving (most energetic) molecules escape from the surface, so the average kinetic energy of the molecules left behind decreases.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igphy_thermal_s3_004', 'topic_igcse_physics_thermal', 'subj_igcse_physics', 'igcse', NULL, NULL, 'Which surface is the best emitter of infrared radiation?', 'multiple_choice', NULL, '["A. A shiny black surface","B. A dull (matt) black surface","C. A dull white surface","D. A shiny white surface"]', 'B', 'Dull black surfaces are the best absorbers and the best emitters of infrared radiation. Shiny surfaces reflect infrared rather than emitting it efficiently, and white or light-coloured surfaces emit less strongly than black ones, so a shiny white surface is the worst emitter of the four. Therefore the correct answer is B: A dull (matt) black surface.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igphy_thermal_s3_005', 'topic_igcse_physics_thermal', 'subj_igcse_physics', 'igcse', NULL, NULL, 'Calculate the energy needed to convert 2.0 kg of water at 100 °C completely into steam at 100 °C. The specific latent heat of vaporisation of water is 2.3 × 10⁶ J/kg.', 'multiple_choice', NULL, '["A. 2.3 × 10⁶ J","B. 4.6 × 10⁵ J","C. 4.6 × 10⁶ J","D. 1.15 × 10⁶ J"]', 'C', 'During a change of state the temperature stays constant, so no mcΔT term applies: E = ml = 2.0 × 2.3 × 10⁶ = 4.6 × 10⁶ J. (2.3 × 10⁶ J is the energy for only 1.0 kg; 4.6 × 10⁵ J is a power-of-ten slip; 1.15 × 10⁶ J divides by the mass instead of multiplying.) Therefore the correct answer is C: 4.6 × 10⁶ J.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igphy_thermal_s3_006', 'topic_igcse_physics_thermal', 'subj_igcse_physics', 'igcse', NULL, NULL, 'An 800 W immersion heater is placed in 0.20 kg of water. Assuming no thermal energy is lost to the surroundings, calculate the time needed to raise the temperature of the water by 30 °C. (Specific heat capacity of water = 4,200 J/(kg °C).)', 'multiple_choice', NULL, '["A. 3.15 s","B. 63 s","C. 10.5 s","D. 31.5 s"]', 'D', 'The energy required is E = mcΔT = 0.20 × 4,200 × 30 = 25,200 J. Power is energy per unit time, so t = E ÷ P = 25,200 ÷ 800 = 31.5 s. (3.15 s is a power-of-ten slip; 63 s doubles the energy needed; 10.5 s results from tripling the power by mistake.) Therefore the correct answer is D: 31.5 s.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, 'board_cambridge'),
('q_igphy_thermal_s3_007', 'topic_igcse_physics_thermal', 'subj_igcse_physics', 'igcse', NULL, NULL, 'A student pours hot water into a beaker and records its temperature as the water cools to room temperature.', 'structured', NULL, NULL, '(a) Conduction (through the beaker walls and into the table), convection (in the air above and around the beaker) and infrared radiation (emitted by the hot surfaces). (b) Air particles near the hot water gain kinetic energy and move faster; the air expands and its density decreases, so the warm air rises. Cooler, denser air sinks in to take its place, and the cycle repeats as a circulating convection current. (c) Placing a lid on the beaker reduces evaporation and traps the layer of warm air above the water, cutting the energy lost by evaporation and convection (accept: wrapping the beaker in an insulating material reduces conduction through its walls).', '(a) Conduction (through the beaker walls and into the table), convection (in the air above and around the beaker) and infrared radiation (emitted by the hot surfaces). (b) Air particles near the hot water gain kinetic energy and move faster; the air expands and its density decreases, so the warm air rises. Cooler, denser air sinks in to take its place, and the cycle repeats as a circulating convection current. (c) Placing a lid on the beaker reduces evaporation and traps the layer of warm air above the water, cutting the energy lost by evaporation and convection (accept: wrapping the beaker in an insulating material reduces conduction through its walls).', 'medium', '7', '7', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_610_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_igphy_thermal_s3_007_a', 'q_igphy_thermal_s3_007', 'a', 'Name the three main processes by which thermal energy is transferred from the hot water to the surroundings.', '2', 'Conduction (through the beaker walls and into the table), convection (in the air above and around the beaker) and infrared radiation (emitted by the hot surfaces).', '1'),
('sqp_q_igphy_thermal_s3_007_b', 'q_igphy_thermal_s3_007', 'b', 'Explain, in terms of particles, how a convection current forms in the air above the hot water.', '3', 'Air particles near the hot water gain kinetic energy and move faster; the air expands and its density decreases, so the warm air rises. Cooler, denser air sinks in to take its place, and the cycle repeats as a circulating convection current.', '2'),
('sqp_q_igphy_thermal_s3_007_c', 'q_igphy_thermal_s3_007', 'c', 'Suggest one change that would reduce the rate at which the water cools, and explain why it works.', '2', 'Placing a lid on the beaker reduces evaporation and traps the layer of warm air above the water, cutting the energy lost by evaporation and convection (accept: wrapping the beaker in an insulating material reduces conduction through its walls).', '3');
INSERT INTO _migration_610_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_610_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_610_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'igcse-physics-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_610_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_610_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_610_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'igcse-physics-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/', 0, 1 FROM _migration_610_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_610_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_610_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 7 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_610_expected e ON e.id = r.question_id WHERE r.batch_id IS 'igcse-physics-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 7 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_610_expected e ON e.id = q.id) = 7 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_610_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 3 THEN 1 ELSE 0 END;
